#!/usr/bin/env python3
"""Deterministic integer replay implementation of the CrossCheck protocol.

The public entry point is intentionally small.  This module contains the
topology/flows model, the incremental Democratic Trust Propagation repair,
frozen snapshots, the semantic repair cache, and validation.
"""
from __future__ import annotations

from collections import OrderedDict
import hashlib
import math
from typing import Any, Dict, List, Optional, Sequence, Tuple

PPM = 1_000_000
MAX_DEMAND = 1_000_000_000


def _reduced(numerator: int, denominator: int) -> Tuple[int, int]:
    """Return a nonnegative fraction in lowest terms with a positive denom."""
    if denominator < 0:
        numerator, denominator = -numerator, -denominator
    g = math.gcd(numerator, denominator)
    if g:
        numerator //= g
        denominator //= g
    if denominator == 0:  # Cannot happen for valid settings; keep output safe.
        denominator = 1
    return numerator, denominator


def _agreement(entries: Sequence[Tuple[int, int]], epsilon: int) -> Tuple[int, int]:
    """Select the protocol's agreement band.

    ``entries`` is a sequence of ``(value, positive_integer_weight)``.
    The result is ``(representative, mass)``.  Values are nonnegative
    integers, as are all products in the comparison, so no floating point
    arithmetic is used.
    """
    if not entries:
        return 0, 0

    # Aggregate multiplicities at a value.  Equal measured reports remain
    # separate votes, but for an interval band only their total weight and
    # weighted sum matter.
    by_value: Dict[int, int] = {}
    for value, weight in entries:
        if weight:
            by_value[value] = by_value.get(value, 0) + weight
    if not by_value:
        return 0, 0

    values = sorted(by_value)
    weights = [by_value[v] for v in values]
    n = len(values)
    prefix_w = [0] * (n + 1)
    prefix_vw = [0] * (n + 1)
    for i, (v, w) in enumerate(zip(values, weights)):
        prefix_w[i + 1] = prefix_w[i] + w
        prefix_vw[i + 1] = prefix_vw[i] + v * w

    best_weight = -1
    best_lo = 0
    best_hi = 0
    best_left = 0
    best_right = 0

    j = 0
    for i in range(n):
        if j < i:
            j = i
        lo = values[i]
        # 1e6 * (hi - lo) <= epsilon * hi
        # <=> (1e6 - epsilon) * hi <= 1e6 * lo.
        # epsilon <= 250000, so the left coefficient is positive.
        coef = PPM - epsilon
        while j + 1 < n and coef * values[j + 1] <= PPM * lo:
            j += 1
        hi = values[j]
        weight = prefix_w[j + 1] - prefix_w[i]
        if (weight > best_weight or
                (weight == best_weight and
                 (lo < best_lo or (lo == best_lo and hi < best_hi)))):
            best_weight = weight
            best_lo = lo
            best_hi = hi
            best_left = i
            best_right = j

    mass = prefix_w[best_right + 1] - prefix_w[best_left]
    total_vw = prefix_vw[best_right + 1] - prefix_vw[best_left]
    return total_vw // mass, mass


def _agreement_with_clamp(
    raw_values: Sequence[int], capacity: int, epsilon: int
) -> Tuple[int, int]:
    """Agreement band of a router's trial remainders after clamping."""
    # Trial scenarios each have unit weight.
    return _agreement([(0 if v < 0 else (capacity if v > capacity else v), 1)
                       for v in raw_values], epsilon)


class Flow:
    """A directed canonical flow used by repair evidence."""

    __slots__ = (
        "pair", "src", "dst", "capacity", "kind",
        "source_key", "destination_key", "report_keys",
        "endpoints", "endpoint_dirs",
    )

    def __init__(
        self,
        pair: Tuple[int, int],
        capacity: int,
        kind: str,
        source_key: Optional[str],
        destination_key: Optional[str],
    ) -> None:
        self.pair = pair
        self.src, self.dst = pair
        self.capacity = capacity
        self.kind = kind
        self.source_key = source_key
        self.destination_key = destination_key
        keys: List[str] = []
        if source_key is not None:
            keys.append(source_key)
        if destination_key is not None:
            keys.append(destination_key)
        self.report_keys = tuple(keys)

        if self.src == -1:
            self.endpoints = (self.dst,)
            self.endpoint_dirs = (1,)  # target at this router: incoming
        elif self.dst == -1:
            self.endpoints = (self.src,)
            self.endpoint_dirs = (-1,)  # source at this router: outgoing
        else:
            self.endpoints = (self.src, self.dst)
            # +1 means the router is the flow source (outgoing).
            self.endpoint_dirs = (-1, 1)


class FrozenRepair:
    """Immutable repair publication, safe to share between cache/snapshots."""

    __slots__ = ("links", "order", "counters", "link_map")

    def __init__(
        self,
        links: Tuple[Tuple[int, int, int, int, int], ...],
        order: Tuple[Tuple[int, int], ...],
        counters: Tuple[Tuple[str, int, int, int], ...],
    ) -> None:
        self.links = links
        self.order = order
        self.counters = counters
        self.link_map = {(a, b): (value, n, d)
                         for a, b, value, n, d in links}


class CrossCheck:
    """Replay one stream's topology, settings and events."""

    def __init__(self, topology: Dict[str, Any]) -> None:
        self.topology = topology
        self.nodes: Dict[int, Dict[str, Any]] = {
            node["id"]: node for node in topology["nodes"]
        }
        self.node_name_to_id = {node["name"]: node["id"]
                               for node in topology["nodes"]}
        self.name_to_id = self.node_name_to_id

        external_names = list(topology.get("external_nodes", []))
        self.external_ids = sorted({self.node_name_to_id[name]
                                    for name in external_names})
        self.external_id_set = set(self.external_ids)

        self.flows: List[Flow] = []
        self.flow_by_pair: Dict[Tuple[int, int], int] = {}
        counter_capacity: Dict[str, int] = {}
        internal_flows: List[Tuple[int, int]] = []

        def add_flow(flow: Flow) -> None:
            idx = len(self.flows)
            self.flows.append(flow)
            self.flow_by_pair[flow.pair] = idx
            for key in flow.report_keys:
                counter_capacity[key] = flow.capacity
            if flow.kind == "internal":
                internal_flows.append(flow.pair)

        for link in topology["links"]:
            u = link["source"]
            v = link["target"]
            capacity = link["capacity"]
            uname = self.nodes[u]["name"]
            vname = self.nodes[v]["name"]
            add_flow(Flow((u, v), capacity, "internal",
                          f"low_{uname}_egress_to_{vname}",
                          f"low_{vname}_ingress_from_{uname}"))
            add_flow(Flow((v, u), capacity, "internal",
                          f"low_{vname}_egress_to_{uname}",
                          f"low_{uname}_ingress_from_{vname}"))

        for node_id in self.external_ids:
            name = self.nodes[node_id]["name"]
            capacity = self.nodes[node_id]["external_capacity"]
            # -1 -> A: the report at A is the destination-side origination.
            add_flow(Flow((-1, node_id), capacity, "external_in", None,
                          f"low_{name}_origination"))
            # A -> -1: the report at A is the source-side termination.
            add_flow(Flow((node_id, -1), capacity, "external_out",
                          f"low_{name}_termination", None))

        # Canonical order has semantic meaning for repair-priority ties.
        self.flows.sort(key=lambda f: f.pair)
        self.flow_by_pair = {flow.pair: i for i, flow in enumerate(self.flows)}
        self.internal_flows = [flow.pair for flow in self.flows
                               if flow.kind == "internal"]
        self.external_flows = [flow.pair for flow in self.flows
                               if flow.kind != "internal"]
        self.counter_capacity = counter_capacity
        self.valid_counter_keys = set(counter_capacity)
        self.counter_values: Dict[str, Optional[int]] = {
            key: None for key in counter_capacity
        }

        # Ordered external-demand pairs, including their initial zero values.
        self.demand_pairs = sorted((s, d)
                                   for s in self.external_ids
                                   for d in self.external_ids if s != d)
        self.demands: Dict[Tuple[int, int], int] = {
            pair: 0 for pair in self.demand_pairs
        }

        # Build router incidence once.  Each incidences index and direction
        # are independent of event order.
        routers = sorted(self.nodes)
        self.incident_by_router: Dict[int, List[int]] = {r: [] for r in routers}
        for idx, flow in enumerate(self.flows):
            for router, direction in zip(flow.endpoints, flow.endpoint_dirs):
                self.incident_by_router[router].append(idx)
        self.routers = routers

        # Active route plan: None means the protocol's null plan.  A non-null
        # empty plan is represented by an empty route lookup.
        self.has_routes = False
        self.route_lookup: Optional[Dict[Tuple[int, int],
                                         Tuple[Tuple[Tuple[int, ...], int], ...]]] = None
        self.route_canonical: Optional[Tuple[Any, ...]] = None

        # Filled by replay().
        self.settings: Dict[str, Any] = {}
        self.trials = 0
        self.epsilon = 0
        self.seed = 0
        self.cutoff_num = 0
        self.cutoff_den = 1
        self.bias = 0
        self.tau = 0
        self.gamma_num = 0
        self.gamma_den = 1
        self.cache_slots = 0

        self.cache: "OrderedDict[Any, FrozenRepair]" = OrderedDict()
        self.snapshots: Dict[str, FrozenRepair] = {}

    # ------------------------------------------------------------------
    # State normalization / cache identity
    # ------------------------------------------------------------------
    def _topology_key(self) -> Tuple[Any, ...]:
        nodes = tuple(sorted(
            (node_id, node["name"], node["external_capacity"])
            for node_id, node in self.nodes.items()
        ))
        links = tuple(sorted(
            (min(link["source"], link["target"]),
             max(link["source"], link["target"]),
             link["capacity"])
            for link in self.topology["links"]
        ))
        return nodes, links, tuple(self.external_ids)

    def _measured_inputs_key(self) -> Tuple[Any, ...]:
        return tuple((key, self.counter_values[key])
                     for key in sorted(self.counter_values))

    def _demands_key(self) -> Tuple[Any, ...]:
        return tuple((s, d, self.demands[(s, d)])
                     for s, d in self.demand_pairs)

    def _routes_key(self) -> Any:
        if not self.has_routes:
            return None
        # path entries are already canonicalized (multiset semantics).
        assert self.route_lookup is not None
        return tuple(sorted(
            (s, d, paths)
            for (s, d), paths in self.route_lookup.items()
        ))

    def _cache_key(self) -> Tuple[Any, ...]:
        return (
            self._topology_key(),
            self._measured_inputs_key(),
            self._demands_key(),
            self._routes_key(),
            (self.seed, self.trials, self.epsilon),
        )

    # ------------------------------------------------------------------
    # Events
    # ------------------------------------------------------------------
    def _handle_patch(self, event: Dict[str, Any]) -> Dict[str, Any]:
        reject = {"op": "patch", "accepted": False}
        accept = {"op": "patch", "accepted": True}

        if type(event) is not dict or set(event.keys()) != {"op", "demands", "counters"}:
            return reject
        if event.get("op") != "patch":
            return reject
        demands = event.get("demands")
        counters = event.get("counters")
        if type(demands) is not list or type(counters) is not dict:
            return reject

        parsed_demands: List[Tuple[Tuple[int, int], int]] = []
        seen_pairs = set()
        for entry in demands:
            if type(entry) is not list or len(entry) != 3:
                return reject
            src, dst, value = entry
            if (type(src) is not int or type(dst) is not int or
                    type(value) is not int):
                return reject
            if src == dst or src not in self.external_id_set or dst not in self.external_id_set:
                return reject
            if value < 0 or value > MAX_DEMAND:
                return reject
            pair = (src, dst)
            if pair in seen_pairs:
                return reject
            seen_pairs.add(pair)
            parsed_demands.append((pair, value))

        parsed_counters: List[Tuple[str, Optional[int]]] = []
        allowed_annotation_keys = {"perturbed", "ground_truth",
                                   "corrected", "confidence"}
        for key, cell in counters.items():
            if key not in self.counter_capacity:
                return reject
            if cell is None:
                value: Optional[int] = None
            elif type(cell) is dict:
                if "perturbed" not in cell:
                    return reject
                if not set(cell.keys()).issubset(allowed_annotation_keys):
                    return reject
                perturbed = cell["perturbed"]
                if perturbed is None:
                    value = None
                else:
                    capacity = self.counter_capacity[key]
                    if type(perturbed) is not int:
                        return reject
                    if perturbed < 0 or perturbed > capacity:
                        return reject
                    value = perturbed
            else:
                return reject
            parsed_counters.append((key, value))

        # Everything validated: applying is now atomic with respect to the
        # accepted patch.
        for pair, value in parsed_demands:
            self.demands[pair] = value
        for key, value in parsed_counters:
            self.counter_values[key] = value
        return accept

    def _handle_routes(self, event: Dict[str, Any]) -> Dict[str, Any]:
        # Routes events are valid by the domain promise.  Still canonicalize
        # fully so path/object/bundle order cannot affect cache identity.
        paths = event.get("paths")
        if paths is None:
            self.has_routes = False
            self.route_lookup = None
            self.route_canonical = None
        else:
            lookup: Dict[Tuple[int, int],
                         Tuple[Tuple[Tuple[int, ...], int], ...]] = {}
            for src_name, destinations in paths.items():
                src_id = self.name_to_id[src_name]
                for dst_name, bundle in destinations.items():
                    dst_id = self.name_to_id[dst_name]
                    entries: List[Tuple[Tuple[int, ...], int]] = []
                    for path_info in bundle:
                        path_tuple = tuple(self.name_to_id[name]
                                           for name in path_info["path"])
                        entries.append((path_tuple, path_info["weight"]))
                    entries.sort()
                    lookup[(src_id, dst_id)] = tuple(entries)
            self.has_routes = True
            self.route_lookup = lookup
            # Store a canonical representation too (the lookup is sufficient,
            # but this makes the route identity explicit and stable).
            self.route_canonical = tuple(sorted(
                (src, dst, entries) for (src, dst), entries in lookup.items()
            ))
        return {"op": "routes", "accepted": True}

    # ------------------------------------------------------------------
    # Demand/path predictions
    # ------------------------------------------------------------------
    def _external_marginals(self) -> Dict[Tuple[int, int], int]:
        outgoing = {node_id: 0 for node_id in self.external_ids}
        incoming = {node_id: 0 for node_id in self.external_ids}
        for (src, dst), demand in self.demands.items():
            if demand:
                outgoing[src] += demand
                incoming[dst] += demand
        result: Dict[Tuple[int, int], int] = {}
        for node_id in self.external_ids:
            result[(-1, node_id)] = outgoing[node_id]
            result[(node_id, -1)] = incoming[node_id]
        return result

    def _predictions(self) -> Tuple[Optional[Dict[Tuple[int, int], int]],
                                    Dict[Tuple[int, int], int]]:
        """Return (internal predictions or None, external marginal predictions).

        Internal predictions are None exactly when the active routing plan is
        null.  External marginal expectations exist either way.
        """
        external = self._external_marginals()
        if not self.has_routes:
            return None, external

        internal: Dict[Tuple[int, int], int] = {
            pair: 0 for pair in self.internal_flows
        }
        assert self.route_lookup is not None
        for (src, dst), entries in self.route_lookup.items():
            demand = self.demands.get((src, dst), 0)
            for path_tuple, weight in entries:
                amount = demand * weight
                for i in range(len(path_tuple) - 1):
                    hop = (path_tuple[i], path_tuple[i + 1])
                    # A valid simple physical path only names physical hops.
                    internal[hop] = internal.get(hop, 0) + amount
        for pair in internal:
            internal[pair] //= 1000
        return internal, external

    def _flow_predictions(self, include_internal: bool) -> Dict[Tuple[int, int], int]:
        internal, external = self._predictions()
        result = dict(external)
        if include_internal and internal is not None:
            result.update(internal)
        return result

    # ------------------------------------------------------------------
    # Repair
    # ------------------------------------------------------------------
    def _build_frozen(self, values: Sequence[int],
                      confidences: Sequence[Tuple[int, int]]) -> FrozenRepair:
        links: List[Tuple[int, int, int, int, int]] = []
        for idx, flow in enumerate(self.flows):
            value = values[idx]
            n, d = confidences[idx]
            n, d = _reduced(n, d)
            links.append((flow.src, flow.dst, value, n, d))

        order = tuple(tuple(self.flows[idx].pair)
                      for idx in range(len(self.flows)))
        # The publication order is recorded by the caller below; this helper
        # only fixes the signature.  (See _run_repair for actual order.)
        counters: List[Tuple[str, int, int, int]] = []
        for idx, flow in enumerate(self.flows):
            _, _, value, n, d = links[idx]
            for key in flow.report_keys:
                counters.append((key, value, n, d))
        counters.sort(key=lambda item: item[0])
        return FrozenRepair(tuple(links), order, tuple(counters))

    def _run_repair(self) -> FrozenRepair:
        flow_count = len(self.flows)
        if flow_count == 0:
            return FrozenRepair((), (), ())

        trials = self.trials
        epsilon = self.epsilon
        seed = self.seed

        internal_pred, external_pred = self._predictions()
        routes_enabled = internal_pred is not None

        # Ordered baseline pools.  Reports come before the denoised/clamped
        # demand prediction, exactly as in the wire contract.
        pools: List[List[int]] = []
        for flow in self.flows:
            pool: List[int] = []
            if flow.source_key is not None:
                value = self.counter_values[flow.source_key]
                if value is not None:
                    pool.append(value)
            if flow.destination_key is not None:
                value = self.counter_values[flow.destination_key]
                if value is not None:
                    pool.append(value)
            if routes_enabled:
                if flow.kind == "internal":
                    prediction = internal_pred.get(flow.pair, 0)  # type: ignore[union-attr]
                else:
                    prediction = external_pred[flow.pair]
                if prediction > flow.capacity:
                    prediction = flow.capacity
                pool.append(prediction)
            pools.append(pool)

        # Reproducible scenario samples at every router incidence.  The
        # target's own sample cancels from its remainder but is retained here
        # because it affects derived remainders for the other incident flows.
        samples: Dict[Tuple[int, int], List[int]] = {}
        for router in self.routers:
            for idx in self.incident_by_router[router]:
                flow = self.flows[idx]
                pool = pools[idx]
                if not pool:
                    samples[(router, idx)] = [0] * trials
                    continue
                plen = len(pool)
                a, b = flow.pair
                arr: List[int] = []
                prefix = f"{seed}:{router}:"
                suffix = f":{a}:{b}"
                for t in range(trials):
                    digest = hashlib.sha256(
                        f"{prefix}{t}{suffix}".encode("ascii")
                    ).digest()
                    w = int.from_bytes(digest[:8], "big")
                    arr.append(pool[w % plen])
                samples[(router, idx)] = arr

        # Raw (unclamped) remainders for every incidence, and the current
        # router-evidence band for each incidence.
        raw_remainders: Dict[Tuple[int, int], List[int]] = {}
        router_bands: Dict[Tuple[int, int], Tuple[int, int]] = {}
        for router in self.routers:
            incident = self.incident_by_router[router]
            if not incident:
                continue
            for idx in incident:
                raw_remainders[(router, idx)] = [0] * trials

            for t in range(trials):
                total_in = 0
                total_out = 0
                for idx in incident:
                    flow = self.flows[idx]
                    value = samples[(router, idx)][t]
                    if flow.src == router:      # outgoing
                        total_out += value
                    else:                        # incoming
                        total_in += value
                for idx in incident:
                    flow = self.flows[idx]
                    value = samples[(router, idx)][t]
                    if flow.src == router:
                        # Replacement target's old sample is excluded from
                        # the outgoing total, then cancels.
                        remainder = total_in - (total_out - value)
                    else:
                        remainder = total_out - (total_in - value)
                    raw_remainders[(router, idx)][t] = remainder

            for idx in incident:
                router_bands[(router, idx)] = _agreement_with_clamp(
                    raw_remainders[(router, idx)],
                    self.flows[idx].capacity,
                    epsilon,
                )

        def combine(idx: int) -> Tuple[int, int]:
            entries: List[Tuple[int, int]] = [
                (value, trials) for value in pools[idx]
            ]
            for router in self.flows[idx].endpoints:
                rep, mass = router_bands[(router, idx)]
                if mass:
                    entries.append((rep, mass))
            return _agreement(entries, epsilon)

        candidates: List[Tuple[int, int]] = [combine(idx)
                                              for idx in range(flow_count)]
        max_possible_support = 5 * trials
        buckets: List[int] = [0] * (max_possible_support + 1)
        for idx, (_, support) in enumerate(candidates):
            buckets[support] |= (1 << idx)
        current_max = max(candidates[idx][1] for idx in range(flow_count))

        remaining = [True] * flow_count
        fixed_values = [0] * flow_count
        fixed_confidences: List[Tuple[int, int]] = [(0, trials)] * flow_count
        publication_order: List[Tuple[int, int]] = []

        for _ in range(flow_count):
            while current_max > 0 and buckets[current_max] == 0:
                current_max -= 1
            bits = buckets[current_max]
            if not bits:
                # Defensive fallback; valid evidence nonempty should avoid it.
                for candidate_idx in range(flow_count):
                    if remaining[candidate_idx]:
                        bits = 1 << candidate_idx
                        current_max = candidates[candidate_idx][1]
                        break
            low_bit = bits & -bits
            idx = low_bit.bit_length() - 1
            value, support = candidates[idx]
            fixed_values[idx] = value
            fixed_confidences[idx] = (support, trials)
            publication_order.append(self.flows[idx].pair)
            remaining[idx] = False
            buckets[current_max] &= ~low_bit

            # Replace this flow's sampled value with its fixed value in the
            # evidence of every other still-unfixed flow at its endpoints.
            affected = set()
            for router in self.flows[idx].endpoints:
                flow_fixed = self.flows[idx]
                dir_fixed = 1 if flow_fixed.src == router else -1
                old_samples = samples[(router, idx)]
                delta = [fixed_values[idx] - old for old in old_samples]
                for other_idx in self.incident_by_router[router]:
                    if other_idx == idx or not remaining[other_idx]:
                        continue
                    flow_other = self.flows[other_idx]
                    dir_other = 1 if flow_other.src == router else -1
                    coefficient = -dir_other * dir_fixed
                    arr = raw_remainders[(router, other_idx)]
                    if coefficient == 1:
                        for t in range(trials):
                            arr[t] += delta[t]
                    elif coefficient == -1:
                        for t in range(trials):
                            arr[t] -= delta[t]
                    # coefficient is always +/-1 for directed incidence.
                    router_bands[(router, other_idx)] = _agreement_with_clamp(
                        arr, flow_other.capacity, epsilon
                    )
                    affected.add(other_idx)

            for other_idx in affected:
                rep, support_new = combine(other_idx)
                old_support = candidates[other_idx][1]
                candidates[other_idx] = (rep, support_new)
                if support_new != old_support:
                    buckets[old_support] &= ~(1 << other_idx)
                    buckets[support_new] |= (1 << other_idx)
                if support_new > current_max:
                    current_max = support_new

        links = []
        for idx, flow in enumerate(self.flows):
            value = fixed_values[idx]
            n, d = _reduced(*fixed_confidences[idx])
            links.append((flow.src, flow.dst, value, n, d))

        counters: List[Tuple[str, int, int, int]] = []
        for idx, flow in enumerate(self.flows):
            _, _, value, n, d = links[idx]
            for key in flow.report_keys:
                counters.append((key, value, n, d))
        counters.sort(key=lambda item: item[0])

        return FrozenRepair(tuple(links), tuple(publication_order),
                            tuple(counters))

    @staticmethod
    def _publication(frozen: FrozenRepair, request_id: str,
                     cache_hit: bool) -> Dict[str, Any]:
        links = [[a, b, value, n, d]
                 for a, b, value, n, d in frozen.links]
        order = [[a, b] for a, b in frozen.order]
        counters = {key: {"corrected": value,
                          "confidence": [n, d]}
                    for key, value, n, d in frozen.counters}
        return {
            "op": "repair",
            "id": request_id,
            "cache_hit": cache_hit,
            "links": links,
            "order": order,
            "counters": counters,
        }

    def _handle_repair(self, event: Dict[str, Any]) -> Dict[str, Any]:
        request_id = event["id"]

        if self.cache_slots > 0:
            key = self._cache_key()
            cached = self.cache.get(key)
            if cached is not None:
                # Refresh recency (LRU, not FIFO).
                self.cache.move_to_end(key)
                self.snapshots[request_id] = cached
                return self._publication(cached, request_id, True)
        else:
            key = None

        frozen = self._run_repair()
        if self.cache_slots > 0:
            assert key is not None
            while len(self.cache) >= self.cache_slots:
                self.cache.popitem(last=False)
            self.cache[key] = frozen
        # Snapshots are independent of later cache eviction.  FrozenRepair is
        # immutable, so sharing its tuple payload cannot alias mutable state.
        self.snapshots[request_id] = frozen
        return self._publication(frozen, request_id, False)

    # ------------------------------------------------------------------
    # Validation
    # ------------------------------------------------------------------
    def _compare(self, corrected: int, expected: int) -> bool:
        x = corrected * PPM
        y = expected * (PPM - self.bias)
        if x == y:
            return True
        return PPM * abs(x - y) <= self.tau * max(x, y)

    def _handle_validate(self, event: Dict[str, Any]) -> Dict[str, Any]:
        request_id = event["id"]
        frozen = self.snapshots[request_id]
        internal_pred, external_pred = self._predictions()

        checked = 0
        passed = 0
        failed: List[str] = []

        for flow in self.flows:
            if flow.kind == "internal":
                if internal_pred is None:
                    continue
                expected = internal_pred.get(flow.pair, 0)
            else:
                expected = external_pred[flow.pair]

            published = frozen.link_map.get(flow.pair)
            if published is None:
                # With a fixed stream topology this cannot occur.
                continue
            corrected, conf_num, conf_den = published
            if conf_num * self.cutoff_den < self.cutoff_num * conf_den:
                continue

            for key in flow.report_keys:
                checked += 1
                if self._compare(corrected, expected):
                    passed += 1
                else:
                    failed.append(key)

        failed.sort()
        if checked == 0:
            consistent: Optional[bool] = None
        else:
            consistent = passed * self.gamma_den >= checked * self.gamma_num
        return {
            "op": "validate",
            "id": request_id,
            "checked": checked,
            "passed": passed,
            "consistent": consistent,
            "failed": failed,
        }

    # ------------------------------------------------------------------
    # Replay driver
    # ------------------------------------------------------------------
    def replay(self, events: Sequence[Dict[str, Any]],
               settings: Dict[str, Any]) -> List[Dict[str, Any]]:
        self.settings = settings
        self.trials = settings["trials"]
        self.epsilon = settings["epsilon"]
        self.seed = settings["seed"]
        cutoff = settings["cutoff"]
        self.cutoff_num, self.cutoff_den = cutoff[0], cutoff[1]
        self.bias = settings["bias"]
        self.tau = settings["tau"]
        gamma = settings["gamma"]
        self.gamma_num, self.gamma_den = gamma[0], gamma[1]
        self.cache_slots = settings["cache_slots"]

        answers: List[Dict[str, Any]] = []
        for event in events:
            op = event.get("op")
            if op == "patch":
                answers.append(self._handle_patch(event))
            elif op == "routes":
                answers.append(self._handle_routes(event))
            elif op == "repair":
                answers.append(self._handle_repair(event))
            elif op == "validate":
                answers.append(self._handle_validate(event))
            else:
                # Outside the promised domain; a deterministic rejection is
                # preferable to producing invalid JSON.
                answers.append({"op": op, "accepted": False})
        return answers
